-- Which migrations have run on this database. READ-ONLY: it changes nothing, so it's safe to run any time.
-- Paste it into the Supabase SQL Editor and press Run. Each row is one file in supabase/migrations/:
--   run           something only that migration makes is there
--   NOT RUN       run that file (in number order, oldest first)
--   repair file   no check needed: the file is safe to run more than once
-- Each check looks for something the migration leaves behind (a table, function, column, setting or a line only its
-- version of a function has) and was tested on a fresh database: false before the file, true after it and after
-- every later file. Add a row for every new migration (tests/migrationStatus.test.ts fails until you do).

select m.file,
       case when m.ran is null then 'repair file' when m.ran then 'run' else 'NOT RUN' end as status
from (values
